package coralnpu

import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// Memory region descriptor (Scala compile-time only)
// ---------------------------------------------------------------------------

object MemoryRegionType extends Enumeration {
  val IMEM, DMEM, Peripheral = Value
}

/** Describes a contiguous address range in the system memory map.
  *
  * @param base  Base address (inclusive)
  * @param size  Size in bytes
  * @param kind  Region type (IMEM / DMEM / Peripheral)
  */
class MemoryRegion(val base: Int, val size: Int, val kind: MemoryRegionType.Value) {
  /** True when `addr` falls within this region. */
  def contains(addr: Int): Boolean = addr >= base && addr < base + size
}

// ---------------------------------------------------------------------------
// Fabric port bundles
// ---------------------------------------------------------------------------

/** Source-side fabric port (as seen by the fabric / arbiter).
  *
  * From the DUT's perspective (the FabricArbiter or FabricMux):
  *   - readDataAddr / writeDataAddr / writeDataBits / writeDataStrb are INPUTS
  *     (the source drives them).
  *   - readData is an OUTPUT (the DUT drives data back to the source).
  */
class FabricSourcePort(dataBits: Int, addrBits: Int) extends Bundle {
  val readDataAddr  = Flipped(Valid(UInt(addrBits.W)))
  val writeDataAddr = Flipped(Valid(UInt(addrBits.W)))
  val writeDataBits = Input(UInt(dataBits.W))
  val writeDataStrb = Input(UInt(4.W))
  val readData      = Valid(UInt(dataBits.W))
}

/** Downstream fabric output port (as seen by the FabricArbiter / FabricMux).
  *
  * From the DUT's perspective:
  *   - readDataAddr / writeDataAddr / writeDataBits / writeDataStrb are OUTPUTS
  *     (the DUT drives them toward the downstream fabric).
  *   - readData is an INPUT (the downstream fabric drives data back).
  */
class FabricOutPort(dataBits: Int, addrBits: Int) extends Bundle {
  val readDataAddr  = Valid(UInt(addrBits.W))
  val writeDataAddr = Valid(UInt(addrBits.W))
  val writeDataBits = Output(UInt(dataBits.W))
  val writeDataStrb = Output(UInt(4.W))
  val readData      = Flipped(Valid(UInt(dataBits.W)))
}

// ---------------------------------------------------------------------------
// FabricArbiter
// ---------------------------------------------------------------------------

/** Priority arbiter for `n` source ports onto a single downstream fabric port.
  *
  * Arbitration policy: source(0) has highest priority. A source is "busy"
  * if any lower-indexed (higher-priority) source has an active request.
  *
  * The downstream readData response is broadcast to ALL sources simultaneously.
  */
class FabricArbiter(p: Parameters, n: Int = 2) extends Module {
  val addrBits = 32
  val dataBits = p.lsuDataBits

  val io = IO(new Bundle {
    val source     = Vec(n, new FabricSourcePort(dataBits, addrBits))
    val port       = new FabricOutPort(dataBits, addrBits)
    val fabricBusy = Output(Vec(n, Bool()))
  })

  // fabricBusy(i) = OR of (any j < i has a valid request)
  for (i <- 0 until n) {
    val higherPriorityBusy = (0 until i).map { j =>
      io.source(j).readDataAddr.valid || io.source(j).writeDataAddr.valid
    }
    io.fabricBusy(i) := higherPriorityBusy.foldLeft(false.B)(_ || _)
  }

  // Selected source = lowest-index with a valid request
  val selectedRead  = Wire(Bool())
  val selectedWrite = Wire(Bool())
  val selectedAddr  = Wire(UInt(addrBits.W))
  val selectedWData = Wire(UInt(dataBits.W))
  val selectedWStrb = Wire(UInt(4.W))

  selectedRead  := false.B
  selectedWrite := false.B
  selectedAddr  := 0.U
  selectedWData := 0.U
  selectedWStrb := 0.U

  // Priority mux: higher-index sources only win when no lower source is active.
  // Build from lowest (highest priority) to highest index.
  // We iterate in reverse so that source(0) takes final precedence.
  for (i <- (n - 1) to 0 by -1) {
    when (io.source(i).readDataAddr.valid) {
      selectedRead  := true.B
      selectedWrite := false.B
      selectedAddr  := io.source(i).readDataAddr.bits
    }.elsewhen (io.source(i).writeDataAddr.valid) {
      selectedRead  := false.B
      selectedWrite := true.B
      selectedAddr  := io.source(i).writeDataAddr.bits
      selectedWData := io.source(i).writeDataBits
      selectedWStrb := io.source(i).writeDataStrb
    }
  }

  // Drive downstream port
  io.port.readDataAddr.valid  := selectedRead
  io.port.readDataAddr.bits   := selectedAddr
  io.port.writeDataAddr.valid := selectedWrite
  io.port.writeDataAddr.bits  := selectedAddr
  io.port.writeDataBits       := selectedWData
  io.port.writeDataStrb       := selectedWStrb

  // Broadcast read response to ALL sources
  for (i <- 0 until n) {
    io.source(i).readData.valid := io.port.readData.valid
    io.source(i).readData.bits  := io.port.readData.bits
  }
}

// ---------------------------------------------------------------------------
// FabricMux
// ---------------------------------------------------------------------------

/** Address-decode mux that routes a single source port to one of several
  * downstream fabric ports based on static memory region descriptors.
  *
  * Addresses are translated to region-relative offsets before being driven
  * onto the selected port.  Accesses to undefined regions are silently dropped.
  *
  * fabricBusy = OR of all periBusy inputs for the currently-addressed region.
  */
class FabricMux(p: Parameters, memoryRegions: Seq[MemoryRegion]) extends Module {
  val addrBits = 32
  val dataBits = p.lsuDataBits
  val n        = memoryRegions.length

  val io = IO(new Bundle {
    val source     = new FabricSourcePort(dataBits, addrBits)
    val ports      = Vec(n, new FabricOutPort(dataBits, addrBits))
    val periBusy   = Input(Vec(n, Bool()))
    val fabricBusy = Output(Bool())
  })

  // Default: all ports get no valid requests
  for (j <- 0 until n) {
    io.ports(j).readDataAddr.valid  := false.B
    io.ports(j).readDataAddr.bits   := 0.U
    io.ports(j).writeDataAddr.valid := false.B
    io.ports(j).writeDataAddr.bits  := 0.U
    io.ports(j).writeDataBits       := io.source.writeDataBits
    io.ports(j).writeDataStrb       := io.source.writeDataStrb
  }

  // Route read requests
  for (j <- 0 until n) {
    val region   = memoryRegions(j)
    val baseU    = region.base.U(addrBits.W)
    val limitU   = (region.base + region.size).U(addrBits.W)
    val rdAddr   = io.source.readDataAddr.bits
    val wrAddr   = io.source.writeDataAddr.bits
    val rdHit    = io.source.readDataAddr.valid  && (rdAddr >= baseU) && (rdAddr < limitU)
    val wrHit    = io.source.writeDataAddr.valid && (wrAddr >= baseU) && (wrAddr < limitU)

    when (rdHit) {
      io.ports(j).readDataAddr.valid := true.B
      io.ports(j).readDataAddr.bits  := rdAddr - baseU
    }
    when (wrHit) {
      io.ports(j).writeDataAddr.valid := true.B
      io.ports(j).writeDataAddr.bits  := wrAddr - baseU
    }
  }

  // Mux read response back to source: pick the active (valid) port response
  val readDataValid = io.ports.map(_.readData.valid).foldLeft(false.B)(_ || _)
  val readDataBits  = io.ports.zipWithIndex.foldLeft(0.U(dataBits.W)) {
    case (acc, (port, _)) => Mux(port.readData.valid, port.readData.bits, acc)
  }
  io.source.readData.valid := readDataValid
  io.source.readData.bits  := readDataBits

  // fabricBusy: OR of all periBusy signals for the currently active region
  // (simplified: OR over all periBusy inputs)
  io.fabricBusy := io.periBusy.foldLeft(false.B)(_ || _)
}

